// Figma Plugin API script generated by `npm run sync:plan` — run with the Figma MCP `use_figma` tool on ONE component file
// (Web / Tablet / Mobile Components). Writes that file's component tokens (D-13):
//   • one local collection per "<Component> / <Group>", its modes = the group's keys in <name>.tokens.json
//   • every variable aliases a SEMANTIC variable of the published "Biowave DS — Foundations" library (imported by key)
//   • hidden from publishing, scopes and code syntax copied from the semantic variable (Dev Mode shows the real code token)
// Never deletes: a variable that left tokens.json moves to `_deprecated/` and is hidden. Variable IDs are kept, so
// bindings in the component sets keep working. Re-running is safe (idempotent).
// After it: run figma-read-tokens.js → npm run sync:verify-tokens -- <file> <dump> → npm run sync:done:tokens:<file>.
const FILE = /*__FILE__*/'';
const COLLECTIONS = /*__COLLECTIONS__*/[];
const LIBRARY = 'Biowave DS — Foundations';

const report = { file: FILE, collections: { created: [], updated: [] }, variables: { created: 0, updated: 0, deprecated: [] }, modes: { created: 0, renamed: 0 }, errors: [] };

// 1. Index the published Foundations library: "<collection>::<name>" → key
const libIndex = new Map();
const libCols = (await figma.teamLibrary.getAvailableLibraryVariableCollectionsAsync()).filter((c) => c.libraryName === LIBRARY);
if (!libCols.length) return { ...report, errors: [`library "${LIBRARY}" is not enabled in this file — enable it (Assets → Libraries) and run again`] };
for (const lc of libCols) for (const lv of await figma.teamLibrary.getVariablesInLibraryCollectionAsync(lc.key)) libIndex.set(`${lc.name}::${lv.name}`, lv.key);

// 2. Import every semantic variable the collections need (once each)
const imported = new Map();
const need = new Set(COLLECTIONS.flatMap((c) => Object.values(c.vars).flatMap((byMode) => Object.values(byMode))));
for (const ref of need) {
  const key = libIndex.get(ref);
  if (!key) { report.errors.push(`not in the published library: ${ref} — publish the Foundations library (Assets → Publish) and run again`); continue; }
  try { imported.set(ref, await figma.variables.importVariableByKeyAsync(key)); }
  catch (e) { report.errors.push(`import failed: ${ref} (${e.message})`); }
}
if (report.errors.length) return report; // nothing written: the file stays as it was

// 3. Collections, modes, variables
const localCols = await figma.variables.getLocalVariableCollectionsAsync();
const localVars = await figma.variables.getLocalVariablesAsync();
const byId = new Map(localVars.map((v) => [v.id, v]));
for (const spec of COLLECTIONS) {
  let col = localCols.find((c) => c.name === spec.collection);
  if (!col) { col = figma.variables.createVariableCollection(spec.collection); report.collections.created.push(spec.collection); }
  else report.collections.updated.push(spec.collection);
  col.hiddenFromPublishing = true;

  // modes: same names and order as tokens.json (the first existing mode is renamed, never deleted)
  const modeId = {};
  spec.modes.forEach((m, i) => {
    let mode = col.modes.find((x) => x.name === m);
    if (!mode && i === 0 && col.modes.length === 1 && !spec.modes.includes(col.modes[0].name)) { col.renameMode(col.modes[0].modeId, m); mode = col.modes[0]; report.modes.renamed++; }
    if (!mode) { const id = col.addMode(m); mode = { modeId: id, name: m }; report.modes.created++; }
    modeId[m] = mode.modeId;
  });

  const existing = col.variableIds.map((id) => byId.get(id)).filter(Boolean);
  for (const [name, byMode] of Object.entries(spec.vars)) {
    const first = imported.get(Object.values(byMode)[0]);
    let v = existing.find((x) => x.name === name);
    if (!v) { v = figma.variables.createVariable(name, col, first.resolvedType); byId.set(v.id, v); report.variables.created++; }
    else report.variables.updated++;
    v.hiddenFromPublishing = true;
    v.scopes = [...first.scopes];
    for (const platform of ['WEB', 'ANDROID', 'iOS']) { const cs = first.codeSyntax?.[platform]; if (cs) v.setVariableCodeSyntax(platform, cs); }
    for (const [m, ref] of Object.entries(byMode)) v.setValueForMode(modeId[m], figma.variables.createVariableAlias(imported.get(ref)));
  }
  // variables no longer in tokens.json → _deprecated (kept, hidden, never deleted)
  for (const v of existing) {
    if (v.name.startsWith('_deprecated/') || v.name in spec.vars) continue;
    v.name = `_deprecated/${v.name}`; v.hiddenFromPublishing = true; v.scopes = [];
    report.variables.deprecated.push(`${spec.collection} › ${v.name}`);
  }
}
return report;
